'use strict';
(()=>{const KEY='gp-nutrition-v2-ergonomic-prototype-only', $=id=>document.getElementById(id), today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')},fmt=(n,d=1)=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:d}),safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const KINDS=[['waist','Taille'],['hips','Hanches'],['glutes','Fessiers'],['thigh','Cuisse'],['chest','Poitrine'],['upperThigh','Haut de cuisse'],['arm','Bras']];
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY))||{}}catch{return {}}},write=db=>localStorage.setItem(KEY,JSON.stringify(db));
const dayOffset=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const avg=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const stat=(label,value)=>'<div class="track-stat"><b>'+value+'</b><small>'+label+'</small></div>';
const diff=(a,b,unit)=>a==null||b==null?'—':(b-a>0?'+':'')+fmt(b-a)+' '+unit;
function chart(target,title,entries,unit){const el=$(target);if(!entries.length){el.innerHTML='<div class="track-chart"><h3>'+title+'</h3><p class="chart-note">Pas encore de données pour ce graphique.</p></div>';return;}const w=320,h=160,pad=28,values=entries.map(x=>x.value),min=Math.min(...values),max=Math.max(...values),spread=Math.max(max-min,1),x=i=>pad+(w-2*pad)*(entries.length===1?.5:i/(entries.length-1)),y=v=>h-pad-(v-min)/spread*(h-2*pad);const coords=entries.map((e,i)=>x(i)+','+y(e.value)).join(' ');const points=entries.map((e,i)=>'<circle cx="'+x(i)+'" cy="'+y(e.value)+'" r="3" fill="#f7c27e"><title>'+safe(e.date)+' : '+fmt(e.value)+' '+unit+'</title></circle>').join('');el.innerHTML='<div class="track-chart"><h3>'+title+'</h3><svg viewBox="0 0 320 160" role="img" aria-label="'+safe(title)+'"><line x1="28" y1="132" x2="292" y2="132" stroke="#6b8176"/><polyline points="'+coords+'" fill="none" stroke="#55d4b3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'+points+'<text x="2" y="20" font-size="11" fill="#e6d9b8">'+fmt(max)+' '+unit+'</text><text x="2" y="151" font-size="11" fill="#e6d9b8">'+fmt(min)+'</text></svg><p class="chart-note">'+entries.length+' relevé(s), du '+safe(entries[0].date)+' au '+safe(entries[entries.length-1].date)+'</p></div>';}
function period(id){const mode=$(id+"-window").value,custom=mode==="custom";$(id+"-custom").hidden=!custom;const end=custom?$(id+"-to").value:today(),start=custom?$(id+"-from").value:dayOffset(end,1-Number(mode));const valid=!!start&&!!end&&start<=end;$(id+"-period-error").hidden=valid;$(id+"-period-error").textContent="Choisis une date de début antérieure ou égale à la date de fin.";return {start,end,valid};}
function renderWeight(){const db=read(),list=Object.entries(db.weights||{}).filter(([date,v])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(Number(v))&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,v])=>({date,value:Number(v)})),range=period('weight'),visible=list.filter(e=>range.valid&&e.date>=range.start&&e.date<=range.end),last=visible.at(-1),previous=visible.at(-2);const summary=stat('Moyenne de la période ('+visible.length+' pesée(s))',visible.length?fmt(avg(visible.map(e=>e.value)))+' kg':'—');$('weight-summary').innerHTML=stat('Dernière pesée',last?fmt(last.value)+' kg':'—')+stat('Depuis la précédente',last&&previous?diff(previous.value,last.value,'kg'):'—')+summary;chart('weight-chart','Évolution du poids',visible,'kg');$('weight-history').innerHTML=visible.slice().reverse().map(e=>'<div class="track-entry"><span>'+e.date+' · '+fmt(e.value)+' kg</span><button data-delete-weight="'+e.date+'">Supprimer</button></div>').join('')||'<p class="tracking-note">Aucune pesée enregistrée.</p>';}
function renderCombined(range){const db=read(),sources=[['combine-weight','Poids',db.weights||{},'#58d9a6'],['combine-waist','Taille',Object.fromEntries(Object.entries(db.measurements||{}).map(([d,v])=>[d,v.waist])),'#f8c078'],['combine-glutes','Fessiers',Object.fromEntries(Object.entries(db.measurements||{}).map(([d,v])=>[d,v.glutes])),'#e67c88']];const selected=sources.filter(([id])=>$(id).checked).map(([id,name,records,color])=>({name,color,entries:Object.entries(records).filter(([date,v])=>range.valid&&date>=range.start&&date<=range.end&&v!=null&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0]))})).filter(s=>s.entries.length);if(!selected.length){$('combined-chart').innerHTML='<div class="track-chart"><h3>Courbes combinées</h3><p class="chart-note">Sélectionne une mesure et enregistre des relevés pour afficher les courbes.</p></div>';return;}const dates=[...new Set(selected.flatMap(s=>s.entries.map(e=>e[0])))].sort(),w=320,h=170,pad=30,x=date=>pad+(w-2*pad)*(dates.length===1?.5:dates.indexOf(date)/(dates.length-1));const lines=selected.map(s=>{const values=s.entries.map(e=>Number(e[1])),min=Math.min(...values),max=Math.max(...values),span=Math.max(max-min,.1),y=v=>h-pad-(v-min)/span*(h-2*pad);return '<polyline fill="none" stroke="'+s.color+'" stroke-width="3" points="'+s.entries.map(([d,v])=>x(d)+','+y(Number(v))).join(' ')+'"/>'+s.entries.map(([d,v])=>'<circle cx="'+x(d)+'" cy="'+y(Number(v))+'" r="3" fill="'+s.color+'"><title>'+s.name+' '+d+' : '+fmt(v)+'</title></circle>').join('')});$('combined-chart').innerHTML='<div class="track-chart"><h3>Courbes combinées — évolution relative</h3><svg viewBox="0 0 320 170" role="img" aria-label="Évolution combinée du poids et des mensurations">'+lines.join('')+'</svg><p class="chart-note">Chaque courbe utilise sa propre échelle. Comparer les tendances, pas les hauteurs entre courbes.</p></div>';}
function renderMeasure(){const db=read(),kind=$('measure-kind').value,list=Object.entries(db.measurements||{}).filter(([date,record])=>record&&Number.isFinite(Number(record[kind]))&&Number(record[kind])>0).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,record])=>({date,value:Number(record[kind])}));const range=period('measure'),visible=list.filter(e=>range.valid&&e.date>=range.start&&e.date<=range.end);chart('measure-chart','Évolution : '+KINDS.find(x=>x[0]===kind)[1],visible,'cm');renderCombined(range);const from=$('measure-compare-from').value,to=$('measure-compare-to').value,a=(db.measurements||{})[from]?.[kind],b=(db.measurements||{})[to]?.[kind];$('measure-compare').innerHTML=stat('Date de départ',a?fmt(a)+' cm':'—')+stat('Date de fin',b?fmt(b)+' cm':'—')+stat('Évolution',diff(a==null?null:Number(a),b==null?null:Number(b),'cm'));$('measure-history').innerHTML=visible.slice().reverse().map(e=>'<div class="track-entry"><span>'+e.date+' · '+fmt(e.value)+' cm</span><button data-delete-measure="'+e.date+'">Supprimer</button></div>').join('')||'<p class="tracking-note">Aucune mesure pour cette zone.</p>';}
function nutritionTotals(items){return(items||[]).reduce((a,i)=>{const q=Number(i.grams)/100;for(const k of ['kcal','p','c','f'])a[k]+=Number(i[k]||0)*q;return a},{kcal:0,p:0,c:0,f:0})}
function renderNutrition(){const db=read(),mode=$('nutrition-window').value,custom=mode==='custom';$('nutrition-custom').hidden=!custom;const end=custom?$('nutrition-to').value:today(),start=custom?$('nutrition-from').value:dayOffset(end,1-Number(mode));const valid=!!start&&!!end&&start<=end;const count=valid?Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1:0;$('nutrition-period-error').hidden=valid;$('nutrition-period-error').textContent='Choisis une date de début antérieure ou égale à la date de fin.';const entries=Object.entries(db.days||{}).filter(([date,r])=>valid&&date>=start&&date<=end&&r.complete===true).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,r])=>({date,...nutritionTotals(r.items)}));$('nutrition-summary').innerHTML=stat('Journées complètes',entries.length+' / '+count)+[['kcal','Calories','kcal'],['p','Protéines','g'],['c','Glucides','g'],['f','Lipides','g']].map(([k,label,unit])=>stat('Moyenne '+label,entries.length?fmt(avg(entries.map(e=>e[k])))+' '+unit:'—')).join('');chart('nutrition-chart','Calories journalières (jours complets)',entries.map(e=>({date:e.date,value:e.kcal})),'kcal');$('nutrition-history').innerHTML=entries.slice().reverse().map(e=>'<div class="track-entry"><span>'+e.date+' · '+fmt(e.kcal)+' kcal · '+fmt(e.p)+' g prot.</span></div>').join('')||'<p class="tracking-note">Aucune journée complète sur cette période.</p>';}
function renderOverview(){const db=read(),weights=Object.entries(db.weights||{}).filter(([d,v])=>Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0])),waists=Object.entries(db.measurements||{}).filter(([d,v])=>Number(v?.waist)>0).sort((a,b)=>a[0].localeCompare(b[0]));const lastW=weights.at(-1),lastT=waists.at(-1);$('overview-weight').textContent=lastW?fmt(lastW[1])+' kg':'— kg';$('overview-waist').textContent=lastT?fmt(lastT[1].waist)+' cm':'— cm';$('overview-weight-change').textContent=weights.length>1?'Depuis la précédente : '+diff(Number(weights.at(-2)[1]),Number(lastW[1]),'kg'):'En attente de 2 pesées';$('overview-waist-change').textContent=waists.length>1?'Depuis la précédente : '+diff(Number(waists.at(-2)[1].waist),Number(lastT[1].waist),'cm'):'En attente de 2 mesures';const recent=weights.filter(([date])=>date>=dayOffset(today(),-29)&&date<=today()).map(([date,value])=>({date,value:Number(value)}));chart('overview-chart','Poids · 30 derniers jours',recent,'kg');}
function render(){renderWeight();renderMeasure();renderNutrition();renderOverview();}
for(const id of ['weight','measure']){$(id+'-from').value=dayOffset(today(),-29);$(id+'-to').value=today();$(id+'-window').addEventListener('change',render);$(id+'-from').addEventListener('change',render);$(id+'-to').addEventListener('change',render);} $('weight-date').value=today();$('measure-date').value=today();$('measure-compare-from').value=dayOffset(today(),-30);$('measure-compare-to').value=today();$('measure-kind').innerHTML=KINDS.map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('');
function openTracking(id){$('tracking-dashboard').hidden=true;$('tracking-detail').hidden=false;document.querySelectorAll('[data-track]').forEach(b=>{const active=b.dataset.track===id;b.setAttribute('aria-pressed',String(active));$('track-'+b.dataset.track).hidden=!active;});render();window.scrollTo(0,0);}
function closeTracking(){$('tracking-dashboard').hidden=false;$('tracking-detail').hidden=true;renderOverview();window.scrollTo(0,0);}
$('tracking-back').addEventListener('click',closeTracking);document.querySelectorAll('[data-tracking-open]').forEach(b=>b.addEventListener('click',()=>openTracking(b.dataset.trackingOpen)));
document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-track]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));for(const id of ['weight','measure','nutrition'])$('track-'+id).hidden=id!==b.dataset.track;render()}));
$('weight-form').addEventListener('submit',e=>{e.preventDefault();const date=$('weight-date').value,v=Number($('weight-value').value);if(!date||!Number.isFinite(v)||v<=0||v>500)return;const db=read();db.weights=db.weights||{};db.weights[date]=v;write(db);render();$('weight-value').value='';});
$('measure-form').addEventListener('submit',e=>{e.preventDefault();const date=$('measure-date').value,kind=$('measure-kind').value,v=Number($('measure-value').value);if(!date||!Number.isFinite(v)||v<=0||v>300)return;const db=read();db.measurements=db.measurements||{};db.measurements[date]=db.measurements[date]||{};db.measurements[date][kind]=v;write(db);render();$('measure-value').value='';});
for(const id of ['combine-weight','combine-waist','combine-glutes'])$(id).addEventListener('change',renderMeasure);$('measure-compare-from').addEventListener('change',renderMeasure);$('measure-compare-to').addEventListener('change',renderMeasure);$('measure-kind').addEventListener('change',renderMeasure);$('measure-from').addEventListener('change',renderMeasure);$('measure-to').addEventListener('change',renderMeasure);$('nutrition-window').addEventListener('change',renderNutrition);$('nutrition-from').value=dayOffset(today(),-29);$('nutrition-to').value=today();$('nutrition-from').addEventListener('change',renderNutrition);$('nutrition-to').addEventListener('change',renderNutrition);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const date=b.dataset.deleteWeight;if(date&&confirm('Supprimer cette pesée ?')){const db=read();delete db.weights[date];write(db);render();}const m=b.dataset.deleteMeasure;if(m&&confirm('Supprimer cette mesure ?')){const db=read();delete db.measurements[m][$('measure-kind').value];write(db);render();}if(b.dataset.page==='suivi'){closeTracking();render();}});
window.addEventListener('storage',render);render();
})();